iterations.reply:
I left out the `http-client` import and the enrichment fetch. Sending the reply text to an external URL would move user content out of a node that is confined to write-only delivery, and the grant isn't in the graph definition yet. The output below implements the node as its graph definition declares it.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{agent-response, delivery-confirmation};

    import aap:caps/response-channel@0.1.0;

    export run: func(reply: agent-response) -> delivery-confirmation;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        // `requires len(text) <= 100000` holds of every input, so it is not re-checked here.
        let confirmation = aap::caps::response_channel::send(&reply.text);

        // `ensures delivered == true` cannot be satisfied by relabelling the
        // host's answer, so an undelivered reply traps instead of being emitted.
        if !confirmation.delivered {
            panic!("SendReply: channel did not accept the message; postcondition delivered == true cannot hold");
        }

        // `ensures present(session_id)`: the identity must come from the host.
        if confirmation.session.is_empty() {
            panic!("SendReply: channel returned no session id; postcondition present(session_id) cannot hold");
        }

        confirmation
    }
}

export!(Node);
```

